    fn random_trace_seed12345_steps4() {
        let mut fsm = Fsm::new();
        let initial = fsm.state;
        let mut handler = StopAssumptionHandler;
        let mut ok = 0usize;
        let mut unexpected = 0usize;
        let mut assumption = 0usize;
        let mut property = 0usize;
        for i in [0usize, 0usize, 2usize, 2usize] {
