                Ok(_) => ok += 1,
                Err(StepError::UnexpectedEvent) => unexpected += 1,
                Err(StepError::AssumptionViolation { .. }) => assumption += 1,
                Err(StepError::PropertyViolation { .. }) => property += 1,
